const siblingNamed = `-- name: SiblingNamed :one
SELECT EXISTS (
    SELECT 1 FROM folders
    WHERE user_id = $1 AND name = $2
      AND id <> $3::bigint
      AND (parent_id = $4::bigint
           OR ($4::bigint IS NULL AND parent_id IS NULL))
)::boolean
`

type SiblingNamedParams struct {
	UserID   string
	Name     string
	ExceptID int64
	ParentID *int64
}

// Whether a folder under this parent (NULL: the top level) already has the
// name, other than the folder itself. The unique constraint would refuse it
// too; asking first is what lets the refusal be a sentence.
func (q *Queries) SiblingNamed(ctx context.Context, arg SiblingNamedParams) (bool, error) {
	row := q.db.QueryRow(ctx, siblingNamed,
		arg.UserID,
		arg.Name,
		arg.ExceptID,
		arg.ParentID,
	)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

const subtreeDepth = `-- name: SubtreeDepth :one
WITH RECURSIVE descendants AS (
    SELECT f.id, 1 AS depth
    FROM folders f WHERE f.parent_id = $1::bigint AND f.user_id = $2
    UNION ALL
    SELECT f.id, d.depth + 1
    FROM folders f JOIN descendants d ON f.parent_id = d.id
    WHERE f.user_id = $2
)
SELECT COALESCE(MAX(depth), 0)::int FROM descendants
`

type SubtreeDepthParams struct {
	ID     int64
	UserID string
}

// How many levels hang below a folder: 0 for a leaf.
func (q *Queries) SubtreeDepth(ctx context.Context, arg SubtreeDepthParams) (int64, error) {
	row := q.db.QueryRow(ctx, subtreeDepth, arg.ID, arg.UserID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

