const turnActions = `-- name: TurnActions :many
SELECT a.id, a.tool_name
FROM agent_action_log a
JOIN new_chat_threads t ON t.id = a.thread_id AND t.user_id = $1
WHERE a.thread_id = $2 AND a.user_id = $1
  AND a.chat_turn_id = $3::text
ORDER BY a.created_at DESC, a.id DESC
`

type TurnActionsParams struct {
	UserID     string
	ThreadID   int64
	ChatTurnID string
}

type TurnActionsRow struct {
	ID       int64
	ToolName string
}

// A turn's actions, the newest first: the order a turn is unwound in, so a
// note written into a folder made in the same turn goes before the folder.
func (q *Queries) TurnActions(ctx context.Context, arg TurnActionsParams) ([]TurnActionsRow, error) {
	rows, err := q.db.Query(ctx, turnActions, arg.UserID, arg.ThreadID, arg.ChatTurnID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TurnActionsRow
	for rows.Next() {
		var i TurnActionsRow
		if err := rows.Scan(&i.ID, &i.ToolName); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
